@@ -0,0 +1,53 @@
+import assert from 'node:assert/strict';
+import {createHash} from 'node:crypto';
+import {readFileSync} from 'node:fs';
+const read=p=>JSON.parse(readFileSync(p,'utf8'));
+const x=read('docs/p9.0.7.2.5-dependency-and-exhaustiveness-ledger.json');
+const prior=read('docs/p9.0.7.2.4-official-version-coverage.json');
+const policy=read('docs/p9.0.4.3-promotion-policy.json');
+assert.equal(x.schema_version,'p90725-dependent-primary-reconciliation-v1');
+assert.equal(x.prerequisite_integrated_ci.head,'203362b549913149cc06b787409723522feb64cb');
+assert.equal(x.prerequisite_integrated_ci.workflow_total,11);
+assert.equal(x.prerequisite_integrated_ci.workflow_success_count,11);
+assert.equal(x.dependency_records.length,4);
+const signed=x.dependency_records.find(a=>a.id==='PMR-2025-94-KZID-VII');
+assert(signed?.git_path);
+const bytes=readFileSync(signed.git_path);
+assert.equal(bytes.length,signed.bytes);
+assert.equal(createHash('sha256').update(bytes).digest('hex'),signed.sha256);
+assert.equal(signed.sha256,'549f70e6373cd5ab7c57d79fa1318ac85db71673684507f55ef39e7113c05a47');
+assert.equal(signed.git_sha1,'ac91d5f0374cdec6b0bfc208fe34acd903022909');
+assert.equal(signed.effective_rule,'AFTER_ONE_MONTH_FROM_ADOPTION_2025_06_09');
+assert.equal(x.dependency_2025_97_constitution_trigger_text_resolved,true);
+assert.equal(x.dependency_2025_97_exact_effective_date_certified,false);
+assert.equal(x.signed_constitutional_document_date_consistency_certified,false);
+assert.equal(signed.official_docx_internal_date_conflict.header_act_date,'2025-06-09');
+assert.equal(signed.official_docx_internal_date_conflict.trailing_tiraspol_date,'2024-06-09');
+assert.match(signed.official_docx_internal_date_conflict.resolution,/UNRESOLVED/);
+const legislative=x.dependency_records.find(a=>a.id==='PMR-2024-339-ZI-VII');
+assert(legislative?.revision_uuid);
+assert.equal(legislative.related_act,'PMR-2024-340-ZI-VII');
+assert.equal(x.dependency_2024_340_exact_effective_date_certified,false);
+assert.equal(x.dependency_2024_97_civil_code_resolved,false);
+assert.equal(x.dependency_2025_223_retroactive_normative_scope_certified,false);
+assert.equal(x.dependency_records.find(a=>a.id==='PMR-2026-32-KZI-VIII').trigger_for_law_97_2025,false);
+assert.equal(x.additional_previously_unindexed_2023_local_government_amendments.length,5);
+assert.equal(x.additional_previously_unindexed_2023_local_government_amendments.filter(a=>a.scope!=='PRE_2023_03_25_BASELINE').length,3);
+assert(x.additional_previously_unindexed_2023_local_government_amendments.every(a=>!a.primary_hashed));
+assert.equal(x.identity_count,85);
+assert.equal(x.identity_rows.length,85);
+assert.deepEqual(x.identity_rows.map(r=>r.actual_id).sort(),prior.identity_rows.map(r=>r.actual_id).sort());
+assert.equal(new Set(x.identity_rows.map(r=>r.actual_id)).size,85);
+assert(x.identity_rows.every(r=>r.legal_md_parent_preserved && !r.direct_identity_change_proven_by_dependencies && !r.direct_identity_change_from_all_period_acts_certified && !r.full_polygon_effective_control_certified && r.acts_pending_exhaustiveness && r.semantic_acceptance==='BLOCKED_INCOMPLETE' && !r.p91_import_allowed));
+assert.equal(x.official_2023_2026_gazette_complete,false);
+assert.equal(x.old_new_legal_archive_parity_complete,false);
+assert.equal(x.all_subordinate_local_decrees_complete,false);
+assert.equal(x.original_binary_for_all_relevant_acts_hashed,false);
+assert.equal(x.law_114_2026_new_archive_search_discrepancy_closed,false);
+assert.equal(x.exhaustive_normative_chain,false);
+assert.equal(x.semantic_acceptance,'BLOCKED_INCOMPLETE');
+assert.equal(x.p91_import_allowed,false);
+assert.equal(x.actual_mutation_allowed,false);
+assert.equal(policy.semantic_acceptance,'BLOCKED_INCOMPLETE');
+assert.equal(policy.p91_import_allowed,false);
+console.log('P90725_DEPENDENCY_FAIL_CLOSED_PASS: original constitutional DOCX SHA256, paired triggers, 5 newly surfaced acts, 85 identities, P9.1 DENIED');
